def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((min(x for y, x in cells),
                            min(y for y, x in cells), color, cells))

    objects.sort(key=lambda obj: obj[0])
    tops = sorted(obj[1] for obj in objects)
    n = len(tops)
    if n % 2:
        target = tops[n // 2]
    else:
        target = (tops[n // 2 - 1] + tops[n // 2]) // 2

    out = [[0] * w for _ in range(h)]
    for _, top, color, cells in objects:
        shift = target - top
        for y, x in cells:
            ny = y + shift
            if 0 <= ny < h:
                out[ny][x] = color

    return out
